pub fn set_at(a: &mut Vec<i32>, i: usize, val: i32) {
    // Safety: caller must ensure i < a.len().
    a[i] = val;
}

pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, n: i32) {
    // Preconditions from the problem statement.
    assert!(n > 0, "N must be positive");
    assert!(n < 1000, "N must be < 1000");
    assert_eq!(sum.len(), 1, "aux array must have length exactly 1");

    let n_usize = n as usize;
    assert_eq!(a.len(), n_usize, "primary array length must equal N");

    let val = n + 1; // safe given constraints

    for idx in 0..n_usize {
        set_at(a, idx, val);
    }

    // Lengths remain unchanged because we only do indexed writes.
    debug_assert_eq!(a.len(), n_usize);
    debug_assert_eq!(sum.len(), 1);
}